#include <algorithm>
#include <limits>
#include <string>
#include <optional>
#include <cassert>
#include <iostream>
using ULONGLONG=unsigned long long;
enum {IDC_SEARCH_TERM,IDC_SEARCH_CASE,IDC_SEARCH_WHOLE_PHRASE,IDC_SEARCH_REGEX,IDC_SEARCH_FILES,IDC_SEARCH_FOLDERS,IDC_SEARCH_OWNER,IDC_SEARCH_SIZE_MIN,IDC_SEARCH_SIZE_MAX,IDC_SEARCH_SIZE_UNITS,IDC_SEARCH_PHYSICAL_MIN,IDC_SEARCH_PHYSICAL_MAX,IDC_SEARCH_PHYSICAL_UNITS};
struct SearchCriteria{std::wstring term;bool caseSensitive,wholePhrase,regex,includeFiles,includeFolders;std::optional<ULONGLONG> sizeMinimum,sizeMaximum,physicalMinimum,physicalMaximum;std::wstring owner;};
struct SearchDlg{std::wstring input;int unit=0;std::wstring GetText(int id)const{return id==IDC_SEARCH_SIZE_MIN?input:L"";}bool IsChecked(int)const{return true;}int GetComboSelection(int)const{return unit;}bool ReadCriteria(SearchCriteria&)const;};
bool SearchDlg::ReadCriteria(SearchCriteria& criteria) const
{
    criteria = {
        .term = GetText(IDC_SEARCH_TERM),
        .caseSensitive = IsChecked(IDC_SEARCH_CASE),
        .wholePhrase = IsChecked(IDC_SEARCH_WHOLE_PHRASE),
        .regex = IsChecked(IDC_SEARCH_REGEX),
        .includeFiles = IsChecked(IDC_SEARCH_FILES),
        .includeFolders = IsChecked(IDC_SEARCH_FOLDERS),
        .owner = GetText(IDC_SEARCH_OWNER)
    };

    const auto readBound = [this](const int controlId, const int unitsId, std::optional<ULONGLONG>& bound)
    {
        const int shift = 10 * std::clamp<int>(GetComboSelection(unitsId), 0, 4);
        const ULONGLONG maximum = std::numeric_limits<ULONGLONG>::max() >> shift;
        const std::wstring text = GetText(controlId);
        if (text.empty()) return true;

        ULONGLONG value = 0;
        for (const wchar_t character : text)
        {
            const auto digit = static_cast<ULONGLONG>(character - L'0');
            if (digit > 9 || value > (maximum - digit) / 10) return false;
            value = value * 10 + digit;
        }
        bound = value << shift;
        return true;
    };

    return readBound(IDC_SEARCH_SIZE_MIN, IDC_SEARCH_SIZE_UNITS, criteria.sizeMinimum) &&
        readBound(IDC_SEARCH_SIZE_MAX, IDC_SEARCH_SIZE_UNITS, criteria.sizeMaximum) &&
        readBound(IDC_SEARCH_PHYSICAL_MIN, IDC_SEARCH_PHYSICAL_UNITS, criteria.physicalMinimum) &&
        readBound(IDC_SEARCH_PHYSICAL_MAX, IDC_SEARCH_PHYSICAL_UNITS, criteria.physicalMaximum) &&
        (!criteria.sizeMinimum || !criteria.sizeMaximum || *criteria.sizeMinimum <= *criteria.sizeMaximum) &&
        (!criteria.physicalMinimum || !criteria.physicalMaximum || *criteria.physicalMinimum <= *criteria.physicalMaximum);
}
int main(){int checks=0;for(int unit=0;unit<=4;++unit){SearchDlg d;d.unit=unit;int shift=unit*10;auto max=std::numeric_limits<ULONGLONG>::max()>>shift;for(auto value:{0ULL,1ULL,9ULL,max-1,max}){d.input=std::to_wstring(value);SearchCriteria c;assert(d.ReadCriteria(c)&&c.sizeMinimum&&*c.sizeMinimum==(value<<shift));++checks;}d.input=unit?std::to_wstring(max+1):L"18446744073709551616";SearchCriteria c;assert(!d.ReadCriteria(c));++checks;for(auto text:{L"-1",L"+1",L" 1",L"1 ",L"1.5",L"1e3",L"１２",L"9999999999999999999999999999999999999999"}){d.input=text;assert(!d.ReadCriteria(c));++checks;}d.input=L"";assert(d.ReadCriteria(c)&&!c.sizeMinimum);++checks;}std::cout<<checks<<" size-bound controls passed\n";}
